head.script:
scwin.onpageload = function () {
    // URL 파라미터에서 sessionId 받기
    var sessionId;

    // localStorage에서 받기
    if (!sessionId) {
        try {
            sessionId = localStorage.getItem('currentSessionId');
            console.log('전달받은 sessionId: ', sessionId);
        } catch (e) {
            alert('세션 아이디를 넘겨받지 못했습니다.')
        }
    }

    if (sessionId) {
        scwin.currentSessionId = sessionId;
        scwin.loadSessionModules(sessionId);
    } else {
        alert("세션 정보를 찾을 수 없습니다. 다시 시도해주세요.");
    }

    // 탭 시스템 초기화
    scwin.initTabSystem();
};

/*----------------------------탭 시스템 관리----------------------------*/

// 탭 시스템 초기화
scwin.initTabSystem = function() {
    scwin.activeTabs = []; // 현재 열린 탭들
    scwin.tabCounter = 0;  // 탭 ID 생성용

    console.log("탭 시스템 초기화 완료");
};

// 모듈 타입 정의
scwin.getModuleType = function(moduleCode) {
    var uiModules = ['CHAT', 'DOCUMENT', 'SIGNATURE', 'FILE', 'CALENDAR', 'SCREEN_VIEW', 'PARTICIPANTS'];
    var actionModules = ['MIC_TOGGLE', 'CAMERA_TOGGLE', 'SCREEN_SHARE', 'RECORD', 'LEAVE'];

    if (uiModules.indexOf(moduleCode) !== -1) {
        return 'UI_MODULE';
    } else if (actionModules.indexOf(moduleCode) !== -1) {
        return 'ACTION_MODULE';
    } else {
        return 'UI_MODULE'; // 기본값
    }
};

// 모듈 배치 정보 로드 함수
scwin.loadSessionModules = function (sessionId) {
    dma_sessionRequest.set("sessionId", sessionId);
    $p.executeSubmission("sbm_getSessionModuleDetails");
};

//--------------------------모듈 불러오기--------------------------

scwin.loadLayout = function () {
    var sessionId = scwin.currentSessionId;

    if (!sessionId) {
        alert("세션 정보가 없습니다.");
        return;
    }

    dma_sessionRequest.set("sessionId", sessionId);
    $p.executeSubmission("sbm_getSessionModuleDetails");
};


scwin.sbm_getSessionModuleDetails_submitdone = function (e) {
    if (e && e.responseJSON && e.responseJSON.elData) {
        var sessionModuleList = e.responseJSON.elData.sessionModuleDetailVoList;

        if (sessionModuleList && sessionModuleList.length > 0) {
            scwin.createModuleButtons(sessionModuleList);
        }
    }
};

scwin.sbm_getSessionModuleDetails_submiterror = function (e) {
    alert("모듈 목록을 불러오는데 실패했습니다.");
};

/*----------------------------모듈 버튼 생성----------------------------*/

// 세션 모듈 정보로 버튼 생성
scwin.createModuleButtons = function(sessionModules) {
    console.log("모듈 버튼 생성 시작:", sessionModules);

    // 버튼 영역들 초기화
    scwin.clearAllButtonAreas();

    // 각 모듈을 해당 위치에 버튼으로 배치
    sessionModules.forEach(function(sessionModule) {
        var config = JSON.parse(sessionModule.sessionModuleConfig);
        var areaId = config.area;

        if (areaId && areaId.indexOf("mf_") === 0) {
            areaId = areaId.replace("mf_fr_session_making_process", "mf");
        }

        var moduleInfo = {
            moduleId: sessionModule.moduleId,
            code: sessionModule.code,
            name: sessionModule.name,
            description: sessionModule.description,
            icon: sessionModule.icon,
            type: scwin.getModuleType(sessionModule.code)
        };

        scwin.createModuleButton(areaId, moduleInfo);
    });
};



// 모든 영역 초기화 함수
scwin.clearAllAreas = function () {
    for (var i = 1; i <= 14; i++) {
        var areaId = "grp_area" + i;
        var areaElement = document.getElementById(areaId);

        if (areaElement) {
            // 스타일 초기화
            areaElement.classList.remove('occupied');

            // 라벨 초기화
            var labelElement = areaElement.querySelector('span');
            if (labelElement) {
                // 원래 라벨로 복원
                var originalLabels = {
                    1: "메인 영역 - 화상채팅 (영역 1)",
                    2: "사이드 패널 (영역 2)",
                    3: "채팅 영역 (영역 3)",
                    4: "도구 영역 (영역 4)",
                    5: "상태 패널 (영역 5)",
                    6: "추가 기능 (영역 6)"
                };

                labelElement.textContent = originalLabels[i];
                labelElement.style.color = "";
                labelElement.style.fontWeight = "";
                labelElement.style.textShadow = "";
            }

            // 데이터 속성 제거
            delete areaElement.dataset.moduleId;
            delete areaElement.dataset.hasModule;
        }
    }
};

// 우측 사이드바 생성
scwin.createRightSidebar = function() {
    // 이미 존재하는지 확인
    if (document.getElementById('right_sidebar')) {
        console.log("우측 사이드바가 이미 존재합니다.");
        return;
    }

    var videoLayout = document.getElementById('grp_screen');
    if (!videoLayout) {
        // WebSquare의 mf_ 접두사로 다시 시도
        videoLayout = document.getElementById('mf_grp_screen');
    }
    if (!videoLayout) {
        console.error("grp_screen 요소를 찾을 수 없습니다.");
        return;
    }

    var rightSidebar = document.createElement('div');
    rightSidebar.id = 'right_sidebar';
    rightSidebar.className = 'right-sidebar';
    rightSidebar.style.cssText = `
        width: 300px;
        background: #f8f9fa;
        border-left: 2px solid #e1e5e9;
        display: flex;
        flex-direction: column;
        padding-top: 10px;
    `;

    videoLayout.appendChild(rightSidebar);

    console.log("우측 사이드바 생성 완료");
};

// 우측 사이드바 존재 여부 확인
scwin.sidebarExists = function() {
    return document.getElementById('right_sidebar') !== null;
};

// 탭 활성화
scwin.activateTab = function(tabId) {
    console.log("탭 활성화 시도:", tabId);

    // 모든 탭 비활성화
    scwin.activeTabs.forEach(function(tab) {
        tab.isActive = (tab.tabId === tabId);
    });

    // 활성화된 탭이 있는지 확인
    var activeTab = scwin.activeTabs.find(function(tab) {
        return tab.isActive;
    });

    if (activeTab) {
        console.log("탭 활성화 성공:", activeTab.tabId, activeTab.moduleInfo.name);
        // UI 업데이트
        scwin.renderTabsToUI();
    } else {
        console.error("활성화할 탭을 찾을 수 없습니다:", tabId);
    }
};

// 탭 닫기
scwin.closeTab = function(tabId) {
    // 탭 목록에서 제거
    scwin.activeTabs = scwin.activeTabs.filter(function(tab) {
        return tab.tabId !== tabId;
    });

    // 모든 탭이 닫혔으면 사이드바 완전 제거
    if (scwin.activeTabs.length === 0) {
        scwin.removeRightSidebar();
        console.log("모든 탭이 닫혔습니다. 사이드바를 제거합니다.");
    } else {
        // 활성 탭이 닫혔으면 첫 번째 탭 활성화
        var hasActiveTab = scwin.activeTabs.some(function(tab) {
            return tab.isActive;
        });

        if (!hasActiveTab) {
            scwin.activeTabs[0].isActive = true;
        }

        scwin.renderTabsToUI();
    }

    console.log("탭 닫기:", tabId, "남은 탭:", scwin.activeTabs.length);
};

// 우측 사이드바 완전 제거
scwin.removeRightSidebar = function() {
    var rightSidebar = document.getElementById('right_sidebar');
    if (rightSidebar) {
        rightSidebar.remove();
        console.log("우측 사이드바 완전 제거 완료");
    }
};

// 탭에 모듈 로드
scwin.loadModuleInTab = function(tabContentElement, moduleInfo) {
    console.log("탭에 모듈 로드:", moduleInfo);

    // 기존 내용 제거
    tabContentElement.innerHTML = '';

    // 모듈별 로딩
    if (moduleInfo.code === 'CHAT') {
        scwin.loadChatModuleInTab(tabContentElement, moduleInfo);
    } else if (moduleInfo.code === 'SIGNATURE') {
        scwin.loadSignatureModuleInTab(tabContentElement, moduleInfo);
    } else if (moduleInfo.code === 'DOCUMENT') {
        scwin.loadDocumentModuleInTab(tabContentElement, moduleInfo);
    } else if (moduleInfo.code === 'PARTICIPANTS') {
        scwin.loadParticipantsModuleInTab(tabContentElement, moduleInfo);
    } else {
        // 기본 모듈 표시
        tabContentElement.innerHTML =
            '<div style="padding: 20px; text-align: center; color: #666;">' +
            '<div style="font-size: 2rem; margin-bottom: 10px;">' + moduleInfo.icon + '</div>' +
            '<div style="font-size: 1.1rem; font-weight: 600; margin-bottom: 5px;">' + moduleInfo.name + '</div>' +
            '<div style="font-size: 0.9rem;">' + moduleInfo.description + '</div>' +
            '</div>';
    }
};

/*----------------------------액션 모듈 실행----------------------------*/

// 액션 모듈 실행
scwin.executeModuleAction = function(moduleInfo) {
    console.log("액션 모듈 실행:", moduleInfo);

    switch(moduleInfo.code) {
        case 'MIC_TOGGLE':
            scwin.toggleMicrophone();
            break;
        case 'CAMERA_TOGGLE':
            scwin.toggleCamera();
            break;
        case 'SCREEN_SHARE':
            scwin.toggleScreenShare();
            break;
        case 'RECORD':
            scwin.toggleRecording();
            break;
        case 'LEAVE':
            scwin.leaveSession();
            break;
        default:
            alert('준비 중인 기능입니다: ' + moduleInfo.name);
    }
};

// 마이크 토글
scwin.toggleMicrophone = function() {
    console.log("마이크 토글 실행");
    alert("마이크가 " + (Math.random() > 0.5 ? "켜졌습니다" : "꺼졌습니다"));
};

// 카메라 토글
scwin.toggleCamera = function() {
    console.log("카메라 토글 실행");
    alert("카메라가 " + (Math.random() > 0.5 ? "켜졌습니다" : "꺼졌습니다"));
};

// 화면 공유 토글
scwin.toggleScreenShare = function() {
    console.log("화면 공유 토글 실행");
    alert("화면 공유가 " + (Math.random() > 0.5 ? "시작되었습니다" : "종료되었습니다"));
};

// 녹화 토글
scwin.toggleRecording = function() {
    console.log("녹화 토글 실행");
    alert("녹화가 " + (Math.random() > 0.5 ? "시작되었습니다" : "종료되었습니다"));
};

// 세션 나가기
scwin.leaveSession = function() {
    if (confirm("정말로 회의를 나가시겠습니까?")) {
        console.log("세션 나가기 실행");
        alert("회의를 나갔습니다");
    }
};

/*----------------------------탭용 모듈 로더들----------------------------*/

// 탭용 채팅 모듈 로더
scwin.loadChatModuleInTab = function(tabContentElement, moduleInfo) {
    try {
        var tempId = 'chat_tab_' + Date.now();
        tabContentElement.id = tempId;

        // $p.loadComponent(tempId, "/InsWebApp/modules/chatting/chatting.xml");
        $p.getFrame("/InsWebApp/modules/chatting/chatting.xml");

        console.log("탭에 채팅 모듈 로드 완료");
    } catch (error) {
        console.error("탭에 채팅 모듈 로드 실패:", error);
        tabContentElement.innerHTML = '<div style="color: red; text-align: center; padding: 20px;">채팅 모듈 로드 실패</div>';
    }
};

// 탭용 서명 모듈 로더
scwin.loadSignatureModuleInTab = function(tabContentElement, moduleInfo) {
    try {
        var tempId = 'signature_tab_' + Date.now();
        tabContentElement.id = tempId;

        $p.loadComponent(tempId, "/InsWebApp/modules/signature/signature_module.xml");
        console.log("탭에 서명 모듈 로드 완료");
    } catch (error) {
        console.error("탭에 서명 모듈 로드 실패:", error);
        tabContentElement.innerHTML = '<div style="text-align: center; padding: 20px;">서명 모듈 로드 실패</div>';
    }
};

// 탭용 문서 모듈 로더
scwin.loadDocumentModuleInTab = function(tabContentElement, moduleInfo) {
    try {
        var tempId = 'document_tab_' + Date.now();
        tabContentElement.id = tempId;

        $p.loadComponent(tempId, "/InsWebApp/modules/document/document_module.xml");
        console.log("탭에 문서 모듈 로드 완료");
    } catch (error) {
        console.error("탭에 문서 모듈 로드 실패:", error);
        tabContentElement.innerHTML = '<div style="text-align: center; padding: 20px;">문서 모듈 로드 실패</div>';
    }
};

// 탭용 참여자 목록 모듈 로더
scwin.loadParticipantsModuleInTab = function(tabContentElement, moduleInfo) {
    console.log("탭에 참여자 목록 모듈 로드:", moduleInfo);

    // 참여자 목록 UI 생성
    tabContentElement.innerHTML = `
        <div style="padding: 15px; height: 100%; overflow-y: auto;">
            <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 15px;">
                <div style="font-weight: 600; color: #2d3748; font-size: 16px;">참여자 목록</div>
                <div style="font-size: 14px; color: #666;">4명 참여</div>
            </div>

            <div style="margin-bottom: 15px;">
                <input type="text" placeholder="참여자 검색..." style="width: 100%; padding: 8px 12px; border: 1px solid #e1e5e9; border-radius: 6px; font-size: 14px; outline: none;">
            </div>

            <div style="display: flex; gap: 8px; margin-bottom: 15px;">
                <button style="flex: 1; padding: 6px 12px; background: #667eea; color: white; border: none; border-radius: 4px; font-size: 12px; cursor: pointer;">모두 음소거</button>
                <button style="flex: 1; padding: 6px 12px; background: #f8f9fa; color: #666; border: 1px solid #e1e5e9; border-radius: 4px; font-size: 12px; cursor: pointer;">초대</button>
            </div>

            <div style="border: 1px solid #e1e5e9; border-radius: 8px; background: white;">
                <div style="padding: 12px; border-bottom: 1px solid #f0f0f0; display: flex; align-items: center; background: #f8f9fa;">
                    <div style="width: 36px; height: 36px; border-radius: 50%; background: #4CAF50; color: white; display: flex; align-items: center; justify-content: center; margin-right: 12px; font-weight: bold; font-size: 14px;">나</div>
                    <div style="flex: 1;">
                        <div style="font-weight: 600; font-size: 14px;">나 (호스트)</div>
                        <div style="font-size: 12px; color: #666;">마이크 켜짐, 카메라 켜짐</div>
                    </div>
                    <div style="display: flex; gap: 4px;">
                        <button style="width: 28px; height: 28px; border: none; border-radius: 4px; background: #4CAF50; color: white; cursor: pointer; font-size: 12px;">������</button>
                        <button style="width: 28px; height: 28px; border: none; border-radius: 4px; background: #2196F3; color: white; cursor: pointer; font-size: 12px;">������</button>
                    </div>
                </div>

                <div style="padding: 12px; border-bottom: 1px solid #f0f0f0; display: flex; align-items: center;">
                    <div style="width: 36px; height: 36px; border-radius: 50%; background: #3674B5; color: white; display: flex; align-items: center; justify-content: center; margin-right: 12px; font-weight: bold; font-size: 14px;">김</div>
                    <div style="flex: 1;">
                        <div style="font-weight: 500; font-size: 14px;">김대리</div>
                        <div style="font-size: 12px; color: #666;">마이크 꺼짐, 카메라 켜짐</div>
                    </div>
                    <div style="display: flex; gap: 4px;">
                        <button style="width: 28px; height: 28px; border: none; border-radius: 4px; background: #f44336; color: white; cursor: pointer; font-size: 12px;">������</button>
                        <button style="width: 28px; height: 28px; border: none; border-radius: 4px; background: #2196F3; color: white; cursor: pointer; font-size: 12px;">������</button>
                    </div>
                </div>

                <div style="padding: 12px; border-bottom: 1px solid #f0f0f0; display: flex; align-items: center;">
                    <div style="width: 36px; height: 36px; border-radius: 50%; background: #3674B5; color: white; display: flex; align-items: center; justify-content: center; margin-right: 12px; font-weight: bold; font-size: 14px;">이</div>
                    <div style="flex: 1;">
                        <div style="font-weight: 500; font-size: 14px;">이과장</div>
                        <div style="font-size: 12px; color: #666;">마이크 켜짐, 카메라 꺼짐</div>
                    </div>
                    <div style="display: flex; gap: 4px;">
                        <button style="width: 28px; height: 28px; border: none; border-radius: 4px; background: #4CAF50; color: white; cursor: pointer; font-size: 12px;">������</button>
                        <button style="width: 28px; height: 28px; border: none; border-radius: 4px; background: #f44336; color: white; cursor: pointer; font-size: 12px;">������</button>
                    </div>
                </div>

                <div style="padding: 12px; display: flex; align-items: center;">
                    <div style="width: 36px; height: 36px; border-radius: 50%; background: #3674B5; color: white; display: flex; align-items: center; justify-content: center; margin-right: 12px; font-weight: bold; font-size: 14px;">박</div>
                    <div style="flex: 1;">
                        <div style="font-weight: 500; font-size: 14px;">박부장</div>
                        <div style="font-size: 12px; color: #666;">마이크 켜짐, 카메라 켜짐</div>
                    </div>
                    <div style="display: flex; gap: 4px;">
                        <button style="width: 28px; height: 28px; border: none; border-radius: 4px; background: #4CAF50; color: white; cursor: pointer; font-size: 12px;">������</button>
                        <button style="width: 28px; height: 28px; border: none; border-radius: 4px; background: #2196F3; color: white; cursor: pointer; font-size: 12px;">������</button>
